insert into public.tracks (id,artist_id,album_id,title,aliases,version,released_year,genre,description,cover_index,source_url,visibility,is_demo) values ('00000002-0000-4000-8000-000000000001','00000001-0000-4000-8000-000000000001',null,'아주 느린 밤',array['A Very Slow Night','아주느린밤']::text[],'original',2025,'인디 록','아주 느린 밤. 하루의 끝에서 잠시 멈춰 서고 싶을 때 떠올릴 법한 음악을 상상하며 만든 예시입니다. 실제 발매된 음원이 아닌 지음 데모 데이터입니다.',0,null,'public',true) on conflict do nothing;
