insert into public.tracks (id,artist_id,album_id,title,aliases,version,released_year,genre,description,cover_index,source_url,visibility,is_demo) values ('00000002-0000-4000-8000-000000000011','00000001-0000-4000-8000-000000000005',null,'여름의 조각',array['Summer Pieces','여름의조각']::text[],'original',2025,'인디 팝','여름의 조각. 하루의 끝에서 잠시 멈춰 서고 싶을 때 떠올릴 법한 음악을 상상하며 만든 예시입니다. 실제 발매된 음원이 아닌 지음 데모 데이터입니다.',10,null,'public',true) on conflict do nothing;
