insert into public.concerts (id,title,venue,starts_at,description,is_demo) values ('00000006-0000-4000-8000-000000000001','느린 숲 페스티벌','서울 · 가상의 숲 스테이지','2027-05-22T06:00:00Z','봄의 끝, 우리가 좋아하는 음악을 더 가까이. 실제 개최되지 않는 데모 공연입니다.',true) on conflict do nothing;
insert into public.music_stories (id,track_id,title,body,source_url,author_id,is_demo,visibility,created_at) values ('00000005-0000-4000-8000-000000000001','00000002-0000-4000-8000-000000000001','소리에 귀 기울이는 또 다른 방법','반복되는 소리를 들으며 자신만의 장면을 떠올려 보세요. 이 글은 기능을 소개하는 독자적 예시이며 실제 곡에 관한 사실 설명이 아닙니다.',null,null,true,'public','2026-10-29T00:00:00Z') on conflict do nothing;
insert into public.music_stories (id,track_id,title,body,source_url,author_id,is_demo,visibility,created_at) values ('00000005-0000-4000-8000-000000000002','00000002-0000-4000-8000-000000000002','한 곡에서 시작하는 작은 기록','정답을 찾기보다 내게 남은 감각을 한 줄로 적어 보세요. 이 글은 데모 해설입니다.',null,null,true,'public','2026-10-29T00:00:00Z') on conflict do nothing;
insert into public.music_stories (id,track_id,title,body,source_url,author_id,is_demo,visibility,created_at) values ('00000005-0000-4000-8000-000000000003','00000002-0000-4000-8000-000000000003','음악을 오래 간직하는 법','곡, 기억, 플레이리스트를 연결하면 나만의 음악 지도가 생깁니다. 데모 안내입니다.',null,null,true,'public','2026-10-29T00:00:00Z') on conflict do nothing;
